metrics.workdir_dsl:
workspace "Parcel Tracker" "A C4 model of the parcel delivery tracking platform." {

    model {

        customer = person "Customer" "A customer who uses the platform to look up the status of their parcels."

        parcelTracker = softwareSystem "Parcel Tracker" "The parcel delivery tracking platform, owned and operated by our company." {
            webPortal = container "Web Portal" "Where customers look up shipments." "Web"
            dispatchService = container "Dispatch Service" "Assigns parcels to couriers." "Service"
            shipmentsDb = container "Shipments Database" "Stores shipments and dispatch records." "Database"
        }

        pricingRulesLibrary = softwareSystem "Pricing Rules Library" "A shared library that computes delivery prices from weight and zone." "Library"

        emailProvider = softwareSystem "Email Delivery Provider" "An email delivery provider operated by a different organization." "Email"

        customer -> webPortal "Looks up the status of their parcels"
        webPortal -> pricingRulesLibrary "Embeds"
        dispatchService -> pricingRulesLibrary "Embeds"
        dispatchService -> emailProvider "Sends customer notification emails"
        webPortal -> shipmentsDb "Stores and retrieves shipments"
        dispatchService -> shipmentsDb "Stores dispatch records"
    }

    views {
        systemContext parcelTracker "SystemContext" "The system context diagram for the Parcel Tracker." {
            include *
            autoLayout
        }

        container parcelTracker "Containers" "The container diagram for the Parcel Tracker." {
            include *
            autoLayout
        }
    }
}
